RECORD_KEYS = ("model", "probe_taken_at", "probe_ok", "probe_evidence", "line_index", "rotation_reason")


def append_log(path, ref, title, seats, votes, result, probe=None):
    names = "; ".join(f"{SEAT_NAMES.get(s, s)} {v['vote']}" for s, v in votes.items())
    outliers = [f"{SEAT_NAMES.get(s, s)}: {v['reason']}" for s, v in votes.items() if v["vote"] in ("No", "ABSOLUTELY NO", "none")]
    body = (f"\n#### Decider {ref}: {title}\n\n"
            f"- Date: {datetime.now(timezone.utc).strftime('%Y-%m-%d')}. Seats: {', '.join(SEAT_NAMES.get(s, s) for s in seats)} "
            "(parallel, read-only, each in a sandboxed scratch clone).\n"
            f"- Votes: {names}.\n"
            f"- Result: {result}. Outliers: {'; '.join(outliers) if outliers else 'none'}.\n")
    for s, v in votes.items():
        if "line_index" in v:     # a vote of the old shape has no record to render
            body += f"- Rotation record {s}: {json.dumps({k: v[k] for k in RECORD_KEYS if k in v})}\n"
    if probe is not None:
        body += f"- Probe in force: {json.dumps(probe)}\n"
    with open(path, "a", encoding="utf-8") as f:
        f.write(body)


def hold_vote_lock(repo):
    """Hold the real checkout for the vote with one ``mob-decider.lock.d/<token>.json`` holder per run.
    Each holder is {"pid", "started", "token"}; release removes only this run's holder, so overlapping votes remain locked."""
    directory = facilitator.decider_holders_dir(repo)
    if directory is None:
        return lambda: None
    token = os.urandom(8).hex()
    mine = json.dumps({"pid": os.getpid(), "started": datetime.now(timezone.utc).isoformat(), "token": token})
    path = directory / f"{token}.json"
    temporary = directory / f"{token}.tmp"
    try:
        directory.mkdir(exist_ok=True)
        descriptor = os.open(temporary, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        with os.fdopen(descriptor, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(mine)
        os.replace(temporary, path)
    except OSError:
        return lambda: None

    def release():
        try:
            path.unlink()
        except OSError as exc:
            print(f"warning: could not release the vote lock {path}: {exc}", file=sys.stderr)
        try:
            directory.rmdir()
        except OSError:
            pass
    return release


