DECIDER = "decider"                 # the owner a live vote's lock names
DECIDER_LOCK = "mob-decider.lock"   # inside the checkout's git dir (git rev-parse --git-path), never a tree file


def pid_alive(pid):
    """Whether process `pid` is running (never signals it: on Windows os.kill would terminate it)."""
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return False
    if pid <= 0:
        return False
    if os.name == "nt":
        import ctypes
        kernel32 = ctypes.windll.kernel32
        handle = kernel32.OpenProcess(0x1000, False, pid)          # PROCESS_QUERY_LIMITED_INFORMATION
        if not handle:
            return kernel32.GetLastError() == 5                     # access denied: it exists
        try:
            code = ctypes.c_ulong()
            return bool(kernel32.GetExitCodeProcess(handle, ctypes.byref(code))) and code.value == 259   # STILL_ACTIVE
        finally:
            kernel32.CloseHandle(handle)
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def decider_lock_path(checkout):
    """The vote lock's file for `checkout` (its git dir's mob-decider.lock), or None when it is not a git checkout."""
    try:
        done = _git(checkout, "rev-parse", "--git-path", DECIDER_LOCK, check=False)
    except (OSError, subprocess.TimeoutExpired):
        return None
    if done.returncode != 0 or not done.stdout.strip():
        return None
    path = Path(done.stdout.strip())
    return path if path.is_absolute() else Path(checkout) / path


def decider_holders_dir(checkout):
    """The directory of ``<token>.json`` vote holders, or None outside git; each records ``pid``, ``started``, and ``token``."""
    path = decider_lock_path(checkout)
    return path.with_name(DECIDER_LOCK + ".d") if path is not None else None


def decider_holders(checkout):
    """Readable ``(path, holder)`` entries from the vote-holder directory; holders have ``pid``, ``started``, and ``token``."""
    directory = decider_holders_dir(checkout)
    if directory is None:
        return []
    holders = []
    try:
        paths = list(directory.glob("*.json"))
    except OSError:
        return holders
    for path in paths:
        try:
            holder = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(holder, dict):
            holders.append((path, holder))
    return holders


def decider_lock_live(checkout):
    """True while a live Decider vote holds `checkout`. Stale rule: a lock whose recorded pid is no longer running (or
    that cannot be read as {"pid": ...}) is ignored, so a crashed vote never blocks the facilitator forever."""
    if any(pid_alive(holder.get("pid")) for _, holder in decider_holders(checkout)):
        return True
    path = decider_lock_path(checkout)
    if path is None or not path.is_file():
        return False
    try:
        holder = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return False
    return isinstance(holder, dict) and pid_alive(holder.get("pid"))


